// Hoverslam (suicide burn): the ducted rocket is dropped at 50-70 m AGL, already falling at 10-20 m/s, a few metres
// off a landing pad at the world origin, in light gusty wind. It must light its fans as late as possible and touch down
// upright, on the pad, at ~0 m/s, using as little energy ("fuel") as it can.
// Outputs: Lift upper, Lift lower (fan throttles), Vane X / Vane Z (exhaust vanes; measured on the craft:
//   +Vane X rolls the body negative (drifts +z), +Vane Z pitches it negative (drifts -x)).
// Controller: a burn-profile landing law. The commanded descent rate is v(h) = -sqrt(2*A*(h - H0)) - VF; the engine
// stays off until the craft's fall speed reaches that profile, then a velocity loop tracks it down to the pad. A big
// A means a late, hard burn (little fuel, little margin); a small A means an early, gentle (expensive) one.
// Craft: the ducted rocket plus four grid fins at the top (like Falcon 9): without them it tumbles in an unpowered fall.
// The fans may idle at TI before the burn (more vane authority, costs fuel); evolution decides.
// The vanes run an attitude PD loop whose lean set-point steers the craft over the pad. Evolution tunes the 10 gains.
// The ducted rocket is electric, so "fuel" is the integral of mean fan throttle (throttle-seconds).
// Terms (named reward points, all reported per generation):
//   touchdown - vertical impact speed penalty (the headline: 0 = perfect)
//   upright   - tilt at touchdown
//   pad       - horizontal distance from the pad centre at touchdown
//   fuel      - throttle-seconds burned
//   crash     - one-off penalty: hard impact (> 2.5 m/s), tipped (> 15 deg), flew away, or never landed
function terms() { return ["touchdown", "upright", "pad", "fuel", "crash"]; }

// --- Controller genes (9). The starting values light the engine far too late (A = 22 m/s^2 of assumed braking, more
// than the fans can give) and slam into the pad.
function genome(base) {
  const g = (name, lo, hi, init) => base.genes.push({ name: name, group: "script", min: lo, max: hi, initial: init, sigma: (hi - lo) / 10 });
  g("A", 3, 30, 22);          // braking the profile assumes (m/s^2): later ignition when larger
  g("H0", 0, 6, 0.5);         // profile reaches zero this far above the pad (m)
  g("VF", 0, 3, 0.3);         // final descent rate (m/s)
  g("T0", 0.2, 0.9, 0.5);     // feed-forward throttle while tracking
  g("KV", 0, 0.6, 0.1);       // throttle per m/s of descent-rate error
  g("KA", 0, 0.1, 0.02);      // vane per deg of attitude error
  g("KR", -0.02, 0.02, 0.0);  // vane per deg/s of body rate (sign left to evolution)
  g("KP", 0, 4, 0.5);         // lean (deg) per m off the pad
  g("KD", 0, 8, 1);           // lean (deg) per m/s of drift (braking)
  g("TI", 0, 0.3, 0.05);      // idle throttle before the burn: keeps the exhaust vanes working (costs fuel)
  return base;
}

function init(ctx) { ctx.memory.burnAlt = -1; ctx.memory.fuel = 0; ctx.memory.alt0 = ctx.state.agl; }

// tilt from the craft's attitude sensor (the tail-sitter's body frame: 0 = upright)
function tiltDeg(ctx) { const p = ctx.in["att.pitch"], r = ctx.in["att.roll"]; return Math.min(Math.sqrt(p * p + r * r), 90); }

function control(ctx) {
  const G = ctx.genome, i = ctx.in, s = ctx.state;
  const A = G.get("A"), H0 = G.get("H0"), VF = G.get("VF");
  const h = s.agl, vs = s.vy;
  const vt = -Math.sqrt(2 * A * Math.max(h - H0, 0)) - VF;
  const tilt = tiltDeg(ctx) * Math.PI / 180;
  let thr = (G.get("T0") + G.get("KV") * (vt - vs)) / Math.max(Math.cos(tilt), 0.5);
  const idle = G.get("TI");
  if (vs > vt + 0.5 && ctx.memory.burnAlt < 0) thr = idle;   // still above the profile: idle (vane authority only)
  thr = clamp(thr, 0, 1);
  if (ctx.memory.burnAlt < 0 && thr > idle + 0.05) ctx.memory.burnAlt = h;
  ctx.out["Lift upper"] = thr; ctx.out["Lift lower"] = thr;
  // steer over the pad: lean toward it, brake the drift
  const L = 12, KP = G.get("KP"), KD = G.get("KD");
  const pitchSp = clamp(-KP * s.x - KD * s.vx, -L, L);   // +pitch drifts +x
  const rollSp = clamp(KP * s.z + KD * s.vz, -L, L);     // -roll drifts +z
  const KA = G.get("KA"), KR = G.get("KR");
  ctx.out["Vane Z"] = clamp(KA * (i["att.pitch"] - pitchSp) + KR * i["rate.pitch"], -1, 1);
  ctx.out["Vane X"] = clamp(KA * (i["att.roll"] - rollSp) + KR * i["rate.roll"], -1, 1);
}

function reward(ctx) {
  const o = ctx.out, thr = 0.5 * ((o["Lift upper"] || 0) + (o["Lift lower"] || 0));
  ctx.memory.fuel += thr * ctx.dt;
  return { fuel: -0.6 * thr * ctx.dt };
}

function landed(ctx) { return ctx.state.contact && ctx.t > 0.05; }
function lost(ctx) { const s = ctx.state; return tiltDeg(ctx) > 80 || s.agl > ctx.memory.alt0 + 30; }
function terminate(ctx) { return landed(ctx) || lost(ctx); }

function fitness(ctx) {
  const s = ctx.state, m = ctx.memory;
  const pad = Math.sqrt(s.x * s.x + s.z * s.z);
  const touched = ctx.doneReason === "crash" || landed(ctx);
  if (!touched) {
    // flew away, tipped over in the air, or still airborne at the end: worse than any touchdown
    return { fitness: -150 - Math.min(s.agl, 100) + ctx.sum.fuel,
             terms: { touchdown: -100, upright: 0, pad: 0, crash: -150, fuel: ctx.sum.fuel } };
  }
  const v = Math.max(s.impactSpeed, Math.abs(s.vy));
  const tilt = tiltDeg(ctx);
  const touchdown = -10 * Math.min(v, 30);
  const upright = -1.0 * Math.min(tilt, 45);
  const padT = -3 * Math.min(pad, 15);
  const crash = (v > 2.5 || tilt > 15 || ctx.doneReason === "crash") ? -40 : 0;
  return { fitness: 100 + touchdown + upright + padT + ctx.sum.fuel + crash,
           terms: { touchdown: touchdown, upright: upright, pad: padT, fuel: ctx.sum.fuel, crash: crash } };
}

function descriptor(ctx) { return [ctx.memory.burnAlt, ctx.memory.fuel]; }
